using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class RebirthCamperMountInspect {
public static void Run(){var root=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/REBIRTHCamperFourTurretReview_20261018_v7/FourTurretCamperReview.prefab"));var lines=new List<string>();lines.AddRange(root.GetComponentsInChildren<MeshFilter>(true).Select(f=>f.name).Distinct());foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>!f.name.Contains("Turret_LOD"))){var vs=f.sharedMesh.vertices;var tri=f.sharedMesh.triangles;var parents=Enumerable.Range(0,vs.Length).ToArray();Func<int,int> find=null;find=i=>parents[i]==i?i:parents[i]=find(parents[i]);var keys=new Dictionary<Vector3Int,int>();for(int i=0;i<vs.Length;i++){var v=vs[i];var k=new Vector3Int(Mathf.RoundToInt(v.x*10000),Mathf.RoundToInt(v.y*10000),Mathf.RoundToInt(v.z*10000));if(keys.TryGetValue(k,out int j))parents[find(i)]=find(j);else keys[k]=i;}for(int i=0;i<tri.Length;i+=3){parents[find(tri[i])]=find(tri[i+1]);parents[find(tri[i+2])]=find(tri[i+1]);}foreach(var group in Enumerable.Range(0,vs.Length).GroupBy(i=>find(i))){var pts=group.Select(i=>f.transform.TransformPoint(vs[i])).ToArray();var b=new Bounds(pts[0],Vector3.zero);foreach(var v in pts)b.Encapsulate(v);if(b.center.y>2.85f&&b.center.z< -2.85f&&b.size.magnitude<.4f)lines.Add(f.name+" "+group.Key+" center="+b.center.ToString("F5")+" size="+b.size.ToString("F5"));}}foreach(var r in root.GetComponentsInChildren<Renderer>(true)){var b=r.bounds;if(b.center.y>2.8f&&b.center.z< -2.9f&&b.size.magnitude<.45f)lines.Add("OBJECT "+r.name+" "+b.center.ToString("F5")+" "+b.size.ToString("F5"));}File.WriteAllLines("E:/_Haven/shared/REBIRTHStaged/VehicleStudio/mount-components.txt",lines);UnityEngine.Object.DestroyImmediate(root);}}
